arguments.file_text:
.apply-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.apply-container h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step.active {
    opacity: 1;
}

.step.completed {
    opacity: 1;
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ccc;
    background: #fff;
    color: #666;
}

.step.active .step-circle {
    border-color: #4361ee;
    background: #4361ee;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #2ecc71;
    background: #2ecc71;
    color: #fff;
}

.step-label {
    font-size: 0.75rem;
    margin-top: 0.4rem;
    text-align: center;
    max-width: 80px;
    color: #555;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ddd;
    min-width: 20px;
    max-width: 60px;
    margin: 0 0.25rem;
    align-self: center;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #2ecc71;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
    box-shadow: 0 2px 8px rgba(0,0,0,0.05);
}

.step-content h2 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    box-sizing: border-box;
    transition: border-color 0.2s;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.1);
}

.form-group textarea {
    min-height: 100px;
    resize: vertical;
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: 400 !important;
    font-size: 0.85rem !important;
    margin-top: 0.4rem;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Work Entry & Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e8e8e8;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #333;
}

/* Buttons */
.button-row {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    gap: 1rem;
}

.btn-next,
.btn-back,
.btn-submit,
.btn-add,
.btn-remove {
    padding: 0.6rem 1.5rem;
    border: none;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    font-weight: 500;
    transition: background 0.2s;
}

.btn-next {
    background: #4361ee;
    color: #fff;
    margin-left: auto;
}

.btn-next:hover {
    background: #3651d4;
}

.btn-back {
    background: #e0e0e0;
    color: #333;
}

.btn-back:hover {
    background: #d0d0d0;
}

.btn-submit {
    background: #2ecc71;
    color: #fff;
    padding: 0.8rem 2rem;
    font-size: 1rem;
}

.btn-submit:hover:not(:disabled) {
    background: #27ae60;
}

.btn-submit:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-add {
    background: transparent;
    color: #4361ee;
    border: 1px dashed #4361ee;
    width: 100%;
    padding: 0.8rem;
    margin-bottom: 1rem;
}

.btn-add:hover {
    background: #f0f4ff;
}

.btn-remove {
    background: transparent;
    color: #e74c3c;
    border: 1px solid #e74c3c;
    padding: 0.3rem 0.8rem;
    font-size: 0.8rem;
}

.btn-remove:hover {
    background: #fdf0ef;
}

/* Cover Letter */
.cover-letter-input {
    min-height: 200px !important;
}

.char-count {
    text-align: right;
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.3rem;
}

/* Error Message */
.error-message {
    background: #fdf0ef;
    border: 1px solid #e74c3c;
    color: #c0392b;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

/* Review Section */
.review-section {
    border-bottom: 1px solid #eee;
    padding-bottom: 1.25rem;
    margin-bottom: 1.25rem;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    color: #1a1a2e;
}

.edit-link {
    color: #4361ee;
    cursor: pointer;
    font-size: 0.85rem;
    text-decoration: underline;
}

.edit-link:hover {
    color: #3651d4;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #555;
    font-size: 0.9rem;
}

.review-section dd {
    margin: 0;
    font-size: 0.9rem;
}

.review-entry {
    padding: 0.75rem 0;
    border-top: 1px solid #f0f0f0;
    font-size: 0.9rem;
}

.review-entry:first-child {
    border-top: none;
}

.date-range {
    color: #888;
    font-size: 0.85rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #fafafa;
    padding: 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    line-height: 1.5;
}

/* Confirmation */
